edits.before:
// - Initialize navigation
navigate(this, results, dataFeedback);
/**
 * @desc
 * Listens for all `click` events in the document
 * and closes this menu if clicked outside the list and input field
 * @listens {click} Listens to all `click` events on the document
 **/
document.addEventListener("click", (event) => closeAllLists(event.target, this.inputField));

edits.after:
// - Initialize navigation
navigate(this, results, dataFeedback);
// - Ensure aria-activedescendant reflects selected item id on arrow keys
this.inputField.addEventListener('keydown', function(e) {
  if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
    const listBox = document.getElementById(this.resultsList.idName);
    if (listBox) {
      const selectedItem = listBox.querySelector('[aria-selected="true"]');
      if (selectedItem && selectedItem.id) {
        this.inputField.setAttribute('aria-activedescendant', selectedItem.id);
      } else {
        this.inputField.removeAttribute('aria-activedescendant');
      }
    }
  }
}.bind(this));
/**
 * @desc
 * Listens for all `click` events in the document
 * and closes this menu if clicked outside the list and input field
 * @listens {click} Listens to all `click` events on the document
 **/
document.addEventListener("click", (event) => closeAllLists(event.target, this.inputField));
